#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys


CURRENT_RELEASE = "2.0"


def statement_credit(lines, release):
    rate, cap = {"1.0": (10, 2400), "2.0": (15, 3000)}[release]
    group_credits = {}
    for line in lines:
        group = line["account_id"]
        if release == "2.0":
            group = (group, line["subscription_id"])
        group_credits[group] = (
            group_credits.get(group, 0) + line["charge_cents"] * rate // 100
        )
    # Priority changes individual allocations, but not the capped group total.
    return sum(min(credit, cap) for credit in group_credits.values())


def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    if request.get("command") == "quote":
        release = request.get("release", CURRENT_RELEASE)
        line = request["line"]
        credit_cents = statement_credit([line], release)
        return {
            "release": release,
            "line_id": line["line_id"],
            "credit_cents": credit_cents,
            "amount_due_cents": line["charge_cents"] - credit_cents,
        }
    if request.get("command") == "total":
        release = request.get("release", CURRENT_RELEASE)
        charge_cents = sum(line["charge_cents"] for line in request["lines"])
        credit_cents = statement_credit(request["lines"], release)
        return {
            "release": release,
            "credit_cents": credit_cents,
            "amount_due_cents": charge_cents - credit_cents,
        }
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")
# Meridian Credits

A Python standard-library JSON CLI for monthly loyalty-credit statements.

Run `python3 main.py` with one request on stdin. Check the starter with `python3 -m unittest discover -s tests`. Feature issues supply their interfaces and approved business agreements.

`quote` accepts one `line`; `total` accepts a `lines` array representing a complete monthly statement. Both default to release `"2.0"`: 15% credit rounded down per line, capped at 3,000 cents per `(account_id, subscription_id)` pair. Explicit `"release":"1.0"` retains 10% credit rounded down per line, capped at 2,400 cents per account across subscriptions. Service dates do not select the release.

Run only introduced public suites with `python3 test_public.py --cases PATH`. Suite names and explicit requests identify their release; a change to the current agreement does not invalidate an explicit earlier-release suite.
